{"type":"message","message":{"id":"msg_d94cff7b-7e00-4e43-a9fc-21e32f4d80f4","role":"user","created":1775323657,"content":[{"type":"toolResponse","id":"call_4979eb7a914843a9abbfcf4f","toolResult":{"status":"success","value":{"content":[{"type":"text","text":"The response returned from the tool call was larger (727553 characters) and is stored in the file which you can use other tools to examine or search in: /tmp/goose_mcp_responses/mcp_response_20260404_172737.096333.txt"}],"structuredContent":{"stdout":"{\"document\": {\"elements\": [{\"bbox\": [{\"coord\": [7, 0, 1568, 1990], \"page_id\": 1}], \"content\": null, \"description\": null, \"id\": 0, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [718, 980, 972, 1019], \"page_id\": 3}], \"content\": \"LIBRARY\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [746, 1019, 945, 1054], \"page_id\": 3}], \"content\": \"\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [753, 1063, 957, 1100], \"page_id\": 3}], \"content\": \"\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [664, 1113, 1015, 1166], \"page_id\": 3}], \"content\": \"U.S.URY DEPARTMENT\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1144, 1527, 1351, 1571], \"page_id\": 3}], \"content\": \"LIBRARY\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1149, 1571, 1337, 1614], \"page_id\": 3}], \"content\": \"ROOM 5030\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1130, 1632, 1342, 1684], \"page_id\": 3}], \"content\": \"JUN 2, 3 1972\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1036, 1700, 1433, 1757], \"page_id\": 3}], \"content\": \"TREASURY DEPARTMENT\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [74, 120, 555, 338], \"page_id\": 6}], \"content\": \"TREASURY DEPARTMENT\\nFISCAL SERVICE, BUREAU OF ACCOUNTS\\nOFFICE OF THE COMMISSIONER\\nWASHINGTON 25, D.C.\\nOFFICIAL BUSINESS\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [215, 713, 1332, 1279], \"page_id\": 6}], \"content\": null, \"description\": null, \"id\": 1, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [122, 242, 1303, 544], \"page_id\": 7}], \"content\": \"TREASURY BULLETIN\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [775, 588, 1001, 738], \"page_id\": 7}], \"content\": \"Address:\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [775, 738, 1001, 769], \"page_id\": 7}], \"content\": \"\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [37, 890, 357, 1628], \"page_id\": 7}], \"content\": null, \"description\": null, \"id\": 3, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [489, 1007, 958, 1104], \"page_id\": 7}], \"content\": \"OCTOBER-1960\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [106, 1637, 1303, 1723], \"page_id\": 7}], \"content\": \"UNITED STATES TREASURY DEPARTMENT\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [784, 1705, 1303, 1758], \"page_id\": 7}], \"content\": \"OFFICE OF THE SECRETARY\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [274, 829, 1200, 978], \"page_id\": 8}], \"content\": \"The Treasury Bulletin is for sale by the Superintendent of Documents, U. S. Government Printing Office, Washington 25, D. C. Subscription per year $6.00 domestic, $7.50 foreign. Single copy price varies\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [13, 40, 207, 77], \"page_id\": 9}], \"content\": \"October 1960\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1366, 53, 1387, 82], \"page_id\": 9}], \"content\": \"I\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [482, 154, 889, 194], \"page_id\": 9}], \"content\": \"Table of Contents\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [209, 209, 1201, 1406], \"page_id\": 9}], \"content\": \"<table><tr><td>Treasury financing operations</td><td>A-1</td></tr><tr><td>Summary of Federal fiscal operations</td><td>1</td></tr><tr><td>Budget receipts and expenditures</td><td>2</td></tr><tr><td>Trust account and other transactions</td><td>9</td></tr><tr><td>Cash income and outgo</td><td>13</td></tr><tr><td>Account of the Treasurer of the United States</td><td>19</td></tr><tr><td>Debt outstanding</td><td>21</td></tr><tr><td>Statutory debt limitation</td><td>26</td></tr><tr><td>Public debt operations</td><td>27</td></tr><tr><td>United States savings bonds</td><td>45</td></tr><tr><td>Ownership of Federal securities</td><td>49</td></tr><tr><td>Treasury survey of ownership of Federal securities</td><td>51</td></tr><tr><td>Market quotations on Treasury securities</td><td>55</td></tr><tr><td>Average yields of long-term bonds</td><td>58</td></tr><tr><td>Internal revenue collections</td><td>60</td></tr><tr><td>Monetary statistics</td><td>62</td></tr><tr><td>Capital movements</td><td>66</td></tr><tr><td>Cumulative table of contents</td><td>77</td></tr></table>\", \"description\": null, \"id\": 3, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [202, 1480, 1205, 1547], \"page_id\": 9}], \"content\": \"Note: Where calculations have been made from unrounded figures, the details may not check to the totals shown.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1184, 13, 1420, 52], \"page_id\": 10}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [32, 39, 59, 57], \"page_id\": 10}], \"content\": \"II\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [640, 127, 807, 148], \"page_id\": 10}], \"content\": \"Reporting Bases\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [157, 175, 692, 408], \"page_id\": 10}], \"content\": \"Data on receipts, expenditures, and debt which appear in the \\\"Treasury Bulletin\\\" are based largely on two Treasury financial reports, the \\\"Daily Statement of the United States Treasury\\\" and the \\\"Monthly Statement of Receipts and Expenditures of the United States Government.\\\" Certain monetary statistics are based at least in part on the \\\"Circulation Statement of United States Money.\\\" Where these statements are given as sources for individual tables, they are cited by name only. Their respective reporting bases are described below. For other data in the Bulletin, information on sources or reporting bases is given in connection with the tables themselves.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [152, 436, 693, 676], \"page_id\": 10}], \"content\": \"The monthly statement of receipts and expenditures was first published for February 1954, and replaced the daily statement as the primary source of information on budget results and other receipt and expenditure data classified by type of account. At the same time, the daily statement was changed to a statement of cash deposits and withdrawals affecting the account of the Treasurer of the United States. Both publications have provided comparative figures on their respective bases from the beginning of the fiscal year 1953. The announcement of February 17, 1954, with respect to these reporting changes may be found in the April 1954 issue of the Bulletin.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [152, 700, 693, 958], \"page_id\": 10}], \"content\": \"The monthly statement shows all receipts and expenditures of the Government, including those made from cash accounts held outside the United States Treasury. The information is compiled from reports by the Treasurer of the United States and by all other collecting and disbursing agencies, including those agencies which maintain checking accounts in commercial banks. These reports cover transactions recorded in the accounts of the agencies during the reporting period. The net of the transactions as compiled from these reports is reconciled in the monthly statement to changes in the balance in the Treasurer's account and in cash held outside the Treasurer's account and changes in the public debt outstanding.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [154, 986, 693, 1309], \"page_id\": 10}], \"content\": \"Receipts of taxes and customs duties are reported on a collectione basis. Other receipts are reported partially on a collections basis and partially on a deposite basis. Expenditures, except interest on the public debt, are reported on the basis of checks issued or cash payments made by disbursing officers. Transactions of an interfund or intragovernmental nature are included on the same basis even though the actual issuance of checks may not be involved. Interest on the public debt is included on an accrual basis beginning with figures for June 1955 and the fiscal year 1955. Prior to that, it was included on a due and payable basis. The same reporting basis as that in the monthly statement provides the fiscal year figures for the Treasury's \\\"Combined Statement of Receipts, Expenditures and Balance of the United States Government\\\" and for actual receipts and expenditures in the \\\"Budget of the United States Government.\\\"\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [156, 1333, 698, 1551], \"page_id\": 10}], \"content\": \"Beginning with the final statement for the fiscal year 1960, the monthly statement reports totals for net budget receipts and budget expenditures after deduction of certain inter-fund transactions which are included in the detail of both budget receipts and budget expenditures. The transactions deducted consist of interest payments and minor amounts of certain other payments made by Government agencies to the Treasury. This reporting change was made in accordance with the plan stated in the President's Budget Message of January 18, 1960. It does not affect the surplus or deficit. Figures for earlier periods shown\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [758, 175, 1295, 367], \"page_id\": 10}], \"content\": \"in the Treasury Bulletin were revised to the new reporting basis in the September 1960 issue. The interfund transactions deducted under this procedure do not include payments to the Treasury by wholly owned Government corporations for retirement of their capital stock and for disposition of earnings. These capital transfers have been excluded currently from budget receipts and budget expenditures beginning July 1, 1948, and figures for prior fiscal years back through 1932 were revised accordingly at that time.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [756, 399, 1303, 748], \"page_id\": 10}], \"content\": \"The daily statement on the new basis was first issued for February 17, 1954. In the deposits and withdrawals as shown, no distinction is made as to the type of accounts (budget, trust, etc.). The deposits are on the basis of certificates of deposit cleared through the account of the Treasurer of the United States. Total withdrawals are on the basis of checks paid or cash disbursements made out of the Treasurer's account. Some of the withdrawal classifications shown are reported on the basis of mailed reports of checks issued and are adjusted by means of clearing accounts to the total of checks paid. Except for relatively minor amounts, noncash interfund and other intra-governmental transactions are excluded. The public debt figures in the daily statement also are on a \\\"clearance\\\" basis, with the exception of those issuance and retirement transactions reported on the basis of telegrams from Federal Reserve Banks. Noncash debt transactions are included, however.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [761, 770, 1295, 1052], \"page_id\": 10}], \"content\": \"The daily statement before February 17, 1954, covered not only transactions cleared through the Treasurer's account but also certain Government agency transactions which were handled through commercial bank accounts, and included noncash interfund and other intragovernmental transactions. It provided information similar to that in the present daily statement with respect to the status of the Treasurer's account, and similar to that in the present end-of-month daily statement with respect to debt clearance, retirement, and amount outstanding. Receipts and expenditures, however, were classified by type of account, and the budget results shown in the daily statement were used as the basis for reflecting the results under the President's budget program as enacted by the Congress.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [759, 1071, 1295, 1375], \"page_id\": 10}], \"content\": \"Receipts were on the basis of deposits as they cleared the Treasurer's account. Expenditures cleared through the Treasurer's account were reported on two successive bases. Through 1946 they were on the basis of checks paid by the Treasurer of the United States. Beginning with 1947, expenditures made through the facilities of the Treasury Department's Division of Disbursement were on the basis of checks issued, while certain others, principally those of the Department of Defense and its predecessor organizations, were on the basis of checks paid. Transactions handled through commercial bank accounts, consisting of market transactions in public debt and guaranteed securities, were as reported by the agencies. Interest on the public debt was included on a due and payable basis beginning with November 1949 and on a checks-paid basis prior to that time.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [761, 1399, 1298, 1547], \"page_id\": 10}], \"content\": \"The circulation statement reflects transactions through the Treasurer's account which affect monetary stocks of gold and silver and the amounts of coin and currency in the money supply of the country. It is issued later than the daily statement, however, and the figures are based on transactions consummated during the reporting period even though some may not have cleared the Treasurer's account during that period.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [2, 24, 206, 64], \"page_id\": 11}], \"content\": \"October 1960\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1336, 40, 1390, 70], \"page_id\": 11}], \"content\": \"A-1\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [482, 84, 910, 126], \"page_id\": 11}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [100, 185, 418, 218], \"page_id\": 11}], \"content\": \"September Advance Refunding\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [101, 218, 672, 557], \"page_id\": 11}], \"content\": \"In response to the Treasury offering on September 12 through 20, 1960, holders of four issues of outstanding 2-1/2 percent Treasury bonds maturing from June 15, 1967, through December 15, 1969, exchanged substantial amounts for three issues of 3-1/2 percent bonds maturing in 1980, 1990 (additional issue), and 1998. The bonds eligible for exchange had been issued during the war loans in 1942 and 1943. Subscriptions received and allotted totaled $3,979 million, consisting of $3,395 million from the public and $584 million from government investment accounts.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [100, 560, 670, 705], \"page_id\": 11}], \"content\": \"Advance refunding, the offering announcement had stated, is an important technique in the market-ing of Government securities, involving significant advantages to long-term investors, to the economy, and to the Treasury.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [92, 712, 673, 806], \"page_id\": 11}], \"content\": \"By participating in an advance refunding, the investor gains an immediate increase in interest return, in consideration of his acceptance of a\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [722, 185, 1292, 474], \"page_id\": 11}], \"content\": \"The economy benefits because advance refunding, by facilitating significant debt extension with a minimum change in ownership, avoids the absorption of new long-term funds in cash offerings and consequently does not interfere with the flow of new savings into the private sector of the economy; lessens the adverse market impact of debt extension; improves the functioning of the Government securities market; and reduces potential inflationary pressures.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [726, 498, 1292, 729], \"page_id\": 11}], \"content\": \"By using advance refunding as a debt management technique, the Treasury achieves substantial improvement in the present unbalanced maturity structure of the marketable public debt; reduces its dependence on inflationary bank borrowing; retains its customers for long-term securities; and holds down its long-run cost of managing the public debt.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [725, 745, 1297, 804], \"page_id\": 11}], \"content\": \"The extension of maturity provided by the offering is shown in the accompanying table.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [209, 837, 1181, 1165], \"page_id\": 11}], \"content\": \"<table><tr><th colspan=\\\"2\\\">Treasury bonds eligible for exchange</th><th colspan=\\\"2\\\">Treasury bonds offered in exchange</th></tr><tr><th>Description</th><th>Remaining term to maturity</th><th>Description</th><th>Extension of maturity</th></tr><tr><td>2-1/2% of June 15, 1962-67... (dated May 5, 1942)</td><td>6 yrs., 8\\u00bd mos.</td><td>3-1/2% of Nov. 15, 1980 (dated Oct. 3, 1960)</td><td>13 yrs., 5 mos.</td></tr><tr><td>2-1/2% of Dec. 15, 1963-68... (dated Dec. 1, 1942)</td><td>8 yrs., 2\\u00bd mos.</td><td>3-1/2% of Feb. 15, 1990 (additional to issue dated Feb. 14, 1958)</td><td>21 yrs., 2 mos.</td></tr><tr><td>2-1/2% of June 15, 1964-69... (dated Apr. 15, 1943)</td><td>8 yrs., 8\\u00bd mos.</td><td>3-1/2% of Nov. 15, 1998 (dated Oct. 3, 1960)</td><td>29 yrs., 5 mos.</td></tr><tr><td>2-1/2% of Dec. 15, 1964-69... (dated Sept. 15, 1943)</td><td>9 yrs., 2\\u00bd mos.</td><td></td><td>28 yrs.,11 mos.</td></tr></table>\", \"description\": null, \"id\": 10, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [90, 1181, 669, 1474], \"page_id\": 11}], \"content\": \"longer-term security; avoids any immediate book loss for tax purposes and, if nontaxable, in most instances is not required to take a book loss; acquires a security whose market yield is at least equal to and in most cases slightly higher than that on outstanding issues of comparable maturity; and earns a rate of return over the life of the new security only equalled, if he does not exchange, by reinvesting at maturity of the old security at higher than current market yields.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [710, 1179, 1292, 1483], \"page_id\": 11}], \"content\": \"Pursuant to the provisions of section 1037 (a) of the Internal Revenue Code of 1954 as added by Public Law 36-346 (approved Sept. 22, 1959), the Secretary of the Treasury has declared that no gain or loss shall be recognized for Federal income tax purposes upon the exchange of the eligible 2-1/2 percent bonds solely for the new 3-1/2 percent bonds. For tax purposes, therefore, the investor will carry the new 3-1/2 percent bonds on his books at the same amount as he now is carrying the eligible 2-1/2 per-\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [100, 1511, 1297, 1591], \"page_id\": 11}], \"content\": \"1/ A detailed discussion of the principles and objectives of advance refunding is available in the pamphlet \\\"Debt Management and Advance Refunding,\\\" which may be obtained on request to any Federal Reserve Bank or the U. S. Treasury Department, Washington 25, D. C.\", \"description\": null, \"id\": 13, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [50, 39, 89, 57], \"page_id\": 12}], \"content\": \"A-2\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1202, 28, 1433, 70], \"page_id\": 12}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [447, 79, 1034, 118], \"page_id\": 12}], \"content\": \"Treasury Financing Operations (Continued)\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [142, 159, 729, 292], \"page_id\": 12}], \"content\": \"cent bonds. Gain or loss, if any, upon the obligations surrendered in exchange will be taken into account upon the disposition or redemption of the new bonds.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 292, 726, 565], \"page_id\": 12}], \"content\": \"The Comptroller of the Currency, Board of Governors of the Federal Reserve System, and the Federal Deposit Insurance Corporation have indicated to the Treasury their intent to notify banks under their supervision that they may place the new 3-1/2 percent bonds received in exchange on their books at an amount not greater than the amount at which the 2-1/2 percent bonds surrendered by them are carried on their books.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 561, 723, 711], \"page_id\": 12}], \"content\": \"A holder of the outstanding 2-1/2 percent bonds had the option of accepting the Treasury's exchange offer or of holding the 2-1/2 percent bonds to maturity. Consequently, he could compare his return resulting from exchanging then with the return that\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [771, 159, 1346, 716], \"page_id\": 12}], \"content\": \"to reinvest at that time at a somewhat higher rate than the present market rate for a comparable maturity to do as well as he would have by accepting the exchange offer. For example, if the 2-1/2 percent bonds of December 15, 1964-69, were exchanged for the new 3-1/2 percent 35-year bonds, the rate for the entire 35 years will be 3-1/2 percent. If the exchange was not made and the 2-1/2 percent bonds were held until maturity in December 1969, the holder would have to reinvest the proceeds at that time at a rate of at least 4.14 percent for the remaining 29 years, at compound interest, in order to obtain an average return of 3-1/2 percent for the entire 35 years. This minimum reinvestment rate for the extension period is shown in the tabulation following and is the investment return for the extension period if the exchange was made. The minimum reinvestment rates for the other issues included in the exchange are also shown.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [271, 735, 1238, 1272], \"page_id\": 12}], \"content\": \"<table><tr><td>2-1/2% bonds eligible for exchange</td><td>June 15, 1962-67</td><td>Dec. 15, 1963-68</td><td>June 15, 1964-69</td><td>Dec. 15, 1964-69</td></tr><tr><td>3-1/2% bonds offered in exchange</td><td>Nov. 15, 1980</td><td>Feb. 15, 1990</td><td colspan=\\\"2\\\">Nov. 15, 1998</td></tr><tr><td colspan=\\\"5\\\">Approximate investment return on the 3-1/2% bonds offered in exchange to holders of the eligible 2-1/2% bonds:</td></tr><tr><td>From issue date (Oct. 3, 1960) to maturity 1/2</td><td>3.92%</td><td>3.96%</td><td>3.97%</td><td>3.99%</td></tr><tr><td>For the extension of maturity:</td><td></td><td></td><td></td><td></td></tr><tr><td>Nontaxable holder (or before tax)</td><td>4.23</td><td>4.17</td><td>4.09</td><td>4.14</td></tr><tr><td>Taxable holder; equivalent rate 2/ if cost (book value) of 2-1/2% bond (per $ face value) is:</td><td></td><td></td><td></td><td></td></tr><tr><td>$102 3/</td><td>4.08</td><td>3.99</td><td>3.90</td><td>3.93</td></tr><tr><td>100</td><td>4.11</td><td>4.02</td><td>3.93</td><td>3.96</td></tr><tr><td>98</td><td>4.13</td><td>4.04</td><td>3.95</td><td>3.98</td></tr><tr><td>96</td><td>4.15</td><td>4.06</td><td>3.97</td><td>4.00</td></tr><tr><td>94</td><td>4.17</td><td>4.08</td><td>3.99</td><td>4.02</td></tr><tr><td>92</td><td>4.19</td><td>4.10</td><td>4.01</td><td>4.04</td></tr><tr><td>90</td><td>4.21</td><td>4.12</td><td>4.03</td><td>4.06</td></tr><tr><td>88</td><td>4.23</td><td>4.14</td><td>4.05</td><td>4.08</td></tr><tr><td>86</td><td>4.25</td><td>4.16</td><td>4.07</td><td>4.10</td></tr><tr><td>84</td><td>4.27</td><td>4.18</td><td>4.09</td><td>4.12</td></tr><tr><td>82</td><td>4.29</td><td>4.20</td><td>4.11</td><td>4.14</td></tr></table>\", \"description\": null, \"id\": 7, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [260, 1270, 1230, 1473], \"page_id\": 12}], \"content\": \"1/ Yield to a nontaxable holder, or before tax. Based on mean of bid and ask prices of eligible 2-1/2% bond at noon on September 8, 1960.\\n2/ Rate of return during extension which, combined with 2-1/2% until maturity of eligible 2-1/2% bond, would provide the same return as the appropriate 3-1/2% bond for its full term after tax (on basis of 52 percent tax on ordinary income and 25 percent tax on long-term capital gain at maturity of 3-1.2% bond). To obtain approximate equivalent rates between those for book values shown, interpolation may be applied.\\n3/ Holders with book cost above par are assumed to be amortizing any premium to par at maturity or call date.\", \"description\": null, \"id\": 8, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [158, 1475, 729, 1551], \"page_id\": 12}], \"content\": \"he might obtain by reinvesting the proceeds of the 2-1/2a at maturity.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [158, 1560, 729, 1719], \"page_id\": 12}], \"content\": \"The return for making the extension in the advance refunding is the coupon rate on the new issue. If a nontaxable holder of the 2-1/2 percent bonds did not make the exchange, he will receive only 2-1/2 percent to their maturity and will have\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [779, 1482, 1357, 1722], \"page_id\": 12}], \"content\": \"Exchanges were made on the basis of par for par in multiples of $500, and with adjustments of accrued interest to October 3, 1960, the date interest ceased on the 2-1/2 percent bonds surrendered and interest started on all of the new bonds. Accrued interest (per $100 face amount) payable to the investor on exchanges into the bonds of 1980 and 1998 was $0.751, and into the bonds of 1990,\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [14, 40, 215, 68], \"page_id\": 13}], \"content\": \"October 1960\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1355, 62, 1395, 79], \"page_id\": 13}], \"content\": \"A-3\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [415, 90, 1000, 119], \"page_id\": 13}], \"content\": \"Treasury Financing Operations (Continued)\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [114, 163, 675, 352], \"page_id\": 13}], \"content\": \"$0.285 (net after deducting $0.466 payable by the investor to the Treasury for accrued interest from August 15, 1960, to October 3, 1960, on the 3-1/2 percent bonds of 1990). Interest is payable on the bonds of 1980 and 1998 on May 15 and November 15, and on the bonds of 1990, on February 15 and August 15. All of the new bonds were issued as bearer\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [733, 165, 1292, 357], \"page_id\": 13}], \"content\": \"talities thereof, public pension and retirement and other public funds, international organizations in which the United States holds membership, foreign central banks and foreign states, Federal Reserve Banks, and Government investment accounts were received without deposit. Subscriptions from all others were required to be accompanied by deposit\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [222, 372, 1191, 546], \"page_id\": 13}], \"content\": \"<table><tr><th colspan=\\\"2\\\">Securities eligible for exchange</th><th colspan=\\\"2\\\">Results of advance refunding offer p</th><th colspan=\\\"2\\\">Securities eligible for exchange held by -</th></tr><tr><th rowspan=\\\"2\\\">Description</th><th rowspan=\\\"2\\\">Amount outstanding</th><th colspan=\\\"2\\\">Securities issued in exchange</th><th rowspan=\\\"2\\\">Not exchanged</th><th rowspan=\\\"2\\\">Federal Reserve Banks and Government investment accounts</th><th rowspan=\\\"2\\\">Commercial banks 1/</th></tr><tr><th>Description</th><th>Amount 2/</th></tr></table>\", \"description\": null, \"id\": 5, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [220, 549, 1196, 853], \"page_id\": 13}], \"content\": \"<table><tr><th></th><th colspan=\\\"5\\\">(Amounts in millions of dollars)</th></tr><tr><td>2-1/2% bonds of 1962-67, maturing June 15, 1967..</td><td>2,109</td><td>3-1/2% bonds of 1980</td><td>644</td><td>1,466</td><td>270</td><td>705</td></tr><tr><td>2-1/2% bonds of 1963-68, maturing December 15, 1968.</td><td>2,815</td><td>3-1.2% bonds of 1990</td><td>993</td><td>1,822</td><td>424</td><td>691</td></tr><tr><td>2-1/2% bonds of 1964-69, maturing June 15, 1969..</td><td>3,737</td><td>3-1/2% bonds of 1998</td><td>2,343</td><td>5,206</td><td>455</td><td>785</td></tr><tr><td>2-1/2% bonds of 1964-69, maturing December 15, 1969.</td><td>3,811</td><td></td><td></td><td></td><td>528</td><td>815</td></tr><tr><td>Total</td><td>12,473</td><td></td><td>3,979</td><td>8,494</td><td>1,677</td><td>2,996</td></tr></table>\", \"description\": null, \"id\": 6, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [228, 859, 1172, 1046], \"page_id\": 13}], \"content\": \"As reported in the Treasury Survey of Ownership, August 31, 1960. The offering announcement of September 9 stated that all subscriptions to exchange 2-1/2% bonds of 1962-67 for 3-1/2% bonds of 1980 would be allotted in full; and while there was no precedent which would indicate the extent of investor acceptance, the Treasury was placing a limit of $4.5 billion, or thereabouts, on the combined amounts of 3-1/2% bonds of 1990 and 3-1/2% bonds of 1998 to be issued to the public. In the event the limit was exceeded, subscriptions were subject to allotment on the same basis for both issues. In addition, exchange subscriptions not to exceed $550,000,000, in the aggregate, from Government investment accounts to these two issues were to be allotted in full. Preliminary.\", \"description\": null, \"id\": 7, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [112, 1055, 670, 1161], \"page_id\": 13}], \"content\": \"bonds, with coupons attached, or registered as to principal and interest. They were issued in denominations of $500, $1,000, $5,000, $10,000, $100,000, and $1,000,000.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [112, 1187, 669, 1225], \"page_id\": 13}], \"content\": \"Details of the results are shown in the table above.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [109, 1254, 672, 1388], \"page_id\": 13}], \"content\": \"Banking institutions generally could submit subscriptions for account of customers. Subscriptions from banking institutions for their own account, Federally insured savings and loan associations, States, political subdivisions or instrumen-\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [734, 1060, 1292, 1104], \"page_id\": 13}], \"content\": \"of eligible bonds in an amount equal to 10 percent of the amount of bonds applied for.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [738, 1117, 1292, 1302], \"page_id\": 13}], \"content\": \"The option to redeem the eligible 2-1/2 percent bonds at par and accrued interest prior to maturity for the purpose of using the entire proceeds in payment of Federal estate taxes (if the bonds were owned by the deceased at the time of his death) is also applicable to the new 3-1/2 percent bonds issued in exchange.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [734, 1311, 1291, 1388], \"page_id\": 13}], \"content\": \"A preliminary analysis by investor classes of subscriptions received as of September 30 is shown in the accompanying table.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [219, 1414, 1186, 1785], \"page_id\": 13}], \"content\": \"<table><tr><th>Securities</th><th>Individuals 1/</th><th>Commercial banks (own account)</th><th>All others 2/</th><th>Total</th><th>Individuals 1/</th><th>Commercial banks (own account)</th><th>All others 2/</th><th>Total</th><th>Government investment accounts</th><th>Grand total</th></tr><tr><td colspan=\\\"5\\\">(Number)</td><td colspan=\\\"5\\\">(Amount in millions)</td><td></td></tr><tr><td>3-1/2% bonds of 1980....</td><td>2,423</td><td>333</td><td>1,284</td><td>4,040</td><td>$ 26</td><td>$ 94</td><td>$ 393</td><td>$ 512</td><td>$131</td><td>$ 644</td></tr><tr><td>3-1/2% bonds of 1990....</td><td>2,920</td><td>144</td><td>1,331</td><td>4,395</td><td>23</td><td>47</td><td>707</td><td>777</td><td>216</td><td>993</td></tr><tr><td>3-1/2% bonds of 1998....</td><td>8,762</td><td>321</td><td>2,831</td><td>11,914</td><td>71</td><td>115</td><td>1,920</td><td>2,106</td><td>236</td><td>2,343</td></tr><tr><td>Total....</td><td>14,105</td><td>798</td><td>5,446</td><td>20,349</td><td>119</td><td>256</td><td>3,020</td><td>3,395</td><td>584</td><td>3,979</td></tr></table>\", \"description\": null, \"id\": 14, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [225, 1793, 992, 1866], \"page_id\": 13}], \"content\": \"1/ Includes partnerships and personal trust accounts.\\n2/ Includes insurance companies, mutual savings banks, corporations exclusive of commercial banks, private pension, retirement, and other funds of State and local governments, and dealers and brokers.\", \"description\": null, \"id\": 15, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [1216, 51, 1450, 99], \"page_id\": 14}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [63, 62, 106, 86], \"page_id\": 14}], \"content\": \"A-4\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [466, 108, 1043, 132], \"page_id\": 14}], \"content\": \"Treasury Financing Operations (Continued)\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [158, 200, 626, 220], \"page_id\": 14}], \"content\": \"One-Year Bills and Tax Anticipation Bills\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [158, 228, 720, 393], \"page_id\": 14}], \"content\": \"To obtain cash to refund the bills maturing October 17, 1960, and to provide the funds for the anticipated cash requirements of the Treasury during the remainder of the calendar year, an offering of two issues of Treasury bills was announced on October 6. The offerings consisted of:\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [206, 406, 663, 505], \"page_id\": 14}], \"content\": \"$1-1/2 billion of one-year (364-day) Treasury bills, dated October 17, 1960, to mature October 16, 1961, for cash or in exchange for the $2 billion of 320-day bills maturing October 17, 1960.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [206, 516, 715, 666], \"page_id\": 14}], \"content\": \"3-1/2 billion, or thereabouts, for cash of 244-day Treasury bills, tax anticipation series, dated October 21, 1960, to mature June 22, 1961. The amount included $500 million to cover the reduction in the October 17, 1960, bills. These bills will be acceptable at par in payment of income and profits taxes due June 15, 1961.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [158, 681, 717, 758], \"page_id\": 14}], \"content\": \"Both issues were sold on an auction basis, the one-year bills on October 11 and the 244-day bills on October 18.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [158, 780, 718, 1228], \"page_id\": 14}], \"content\": \"Payment for accepted tenders for the one-year bills was required to be completed on October 17, 1960, in cash or other immediately available funds on in a like face amount of Treasury bills maturing on that date. Cash adjustments were made for differences between the par value of maturing bills accepted in exchange and the issue price of the new bills. For the 244-day bills, any commercial bank qualified as a depositary was permitted to make payment for the bills allotted to itself and its customers by credit in its Treasury tax and loan account up to the amount for which it was qualified in excess of existing deposits. Other subscribers to this issue were required to complete payment for accepted tenders at the prices offered in cash or other immediately available funds on October 21,1960.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [156, 1243, 717, 1467], \"page_id\": 14}], \"content\": \"Tenders for both issues were received without deposit from incorporated banks and trust companies and from responsible and recognized dealers in investment securities. Tenders from others were required to be accompanied by payment of 2 percent of the face amount of Treasury bills applied for, or an express guaranty of payment by an incorporated bank or trust company.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [158, 1483, 717, 1531], \"page_id\": 14}], \"content\": \"Subscribers were required to agree not to purchase or to sell, or to make any agreements with\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [785, 202, 1341, 334], \"page_id\": 14}], \"content\": \"respect to the purchase or sale or other disposition of, the bills for which tenders were submitted under these offerings until after the closing hour for tenders, which was 2:00 p.m., Eastern Daylight Saving time on each of the auction days.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [783, 354, 1342, 459], \"page_id\": 14}], \"content\": \"The new bills of both series were issued in bearer form only, and in denominations of $1,000, $5,000, $10,000, $100,000, $500,000, and $1,000,000 (maturity value).\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [783, 479, 1342, 637], \"page_id\": 14}], \"content\": \"Tenders for the new one-year bills totaled $3,300 million of which $1,500 million were accepted. This amount included $189 million of noncompetitive tenders for $400,000 or less from any one bidder accepted at the average price of accepted competitive bids. The average rate of discount was 3.131 percent.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [783, 659, 1342, 846], \"page_id\": 14}], \"content\": \"Tenders for the tax anticipation bills totaled $5,440 million of which $3,501 million were accepted. This amount included $613 million of noncompetitive tenders for $500,000 or less from any one bidder accepted in full at the average price of accepted competitive bids. The average rate of discount was 2.788 percent.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [785, 879, 1068, 901], \"page_id\": 14}], \"content\": \"13-Week and 26-Week Bills\", \"description\": null, \"id\": 15, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [785, 907, 1342, 1182], \"page_id\": 14}], \"content\": \"September issues of regular weekly Treasury bills totaled $7.8 billion, refunding an equivalent amount of maturing bills. The five new issues of 13-week bills amounted to $5.3 billion, the first and last for $1.0 billion each and the other three for $1.1 billion each. The new issues of 26-week bills amounted to $2.5 billion which consisted of five $0.5 billion issues. All new issues mature in 91 days and 182 days, respectively. Average rates of discount on the new bills were as follows:\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [788, 1254, 1344, 1527], \"page_id\": 14}], \"content\": \"<table><tr><th colspan=\\\"3\\\">13-week (Additional amount of bills of original maturity of 26 weeks)</th><th colspan=\\\"2\\\">26-week</th></tr><tr><th>Date of --</th><th colspan=\\\"2\\\">Approximate equivalent annual average rate</th><th>Date of issue</th><th>Approximate equivalent annual average rate</th></tr><tr><th>Additional issue</th><th>Original issue</th><th></th><th></th><th></th></tr><tr><td>Sept. 18</td><td>June 29</td><td>2.549%</td><td>Sept. 18</td><td>2.825%</td></tr><tr><td>15</td><td>16</td><td>2.520</td><td>15</td><td>2.801</td></tr><tr><td>22</td><td>23</td><td>2.433</td><td>22</td><td>2.743</td></tr><tr><td>29</td><td>30</td><td>2.286</td><td>29</td><td>2.729</td></tr></table>\", \"description\": null, \"id\": 17, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [171, 1577, 1315, 1610], \"page_id\": 14}], \"content\": \"Note: Details of Treasury market financing operations are shown elsewhere in this issue of the Bulletin in the tables on public debt operations.\", \"description\": null, \"id\": 18, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [21, 29, 222, 57], \"page_id\": 15}], \"content\": \"October 1960\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1398, 46, 1412, 66], \"page_id\": 15}], \"content\": \"1\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [481, 99, 933, 116], \"page_id\": 15}], \"content\": \"SUMMARY OF FEDERAL FISCAL OPERATIONS\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [573, 149, 789, 169], \"page_id\": 15}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [6, 167, 1409, 1366], \"page_id\": 15}], \"content\": \"<table><tr><th>Period</th><th colspan=\\\"3\\\">Budget receipts and expenditures</th><th>Net of trust account and other transactions 2/</th><th>Clearing account, etc. 3/</th><th>Net increase in public debt, or decrease (-)</th><th>Net increase in Treasurer's account balance, or decrease (-)</th><th colspan=\\\"4\\\">Levels, end of period</th></tr><tr><th></th><th>Net receipts 1/</th><th>Expenditures 1/</th><th>Surplus, or deficit (-)</th><th></th><th></th><th></th><th>Treasurer's account balance</th><th colspan=\\\"3\\\">Debt outstanding</th><th>Subject to limitation 4/</th></tr><tr><th>Fiscal years:</th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th>Public debt</th><th>Guaranteed securities</th><th>Total Federal securities</th><th></th></tr><tr><td>1948 5/</td><td>41,375</td><td>32,955</td><td>8,419</td><td>-294</td><td>-507</td><td>-5,994</td><td>1,624</td><td>4,932</td><td>252,292</td><td>73</td><td>252,366</td><td>251,542</td></tr><tr><td>1949 5/</td><td>37,663</td><td>39,474</td><td>-1