null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [204, 216, 1426, 278], \"page_id\": 5}], \"content\": \"\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [225, 175, 625, 209], \"page_id\": 6}], \"content\": \"TREASURY DEPARTMENT\", \"description\": null, \"id\": 0, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [147, 221, 701, 245], \"page_id\": 6}], \"content\": \"FISCAL SERVICE, BUREAU OF ACCOUNTS\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [205, 254, 643, 278], \"page_id\": 6}], \"content\": \"OFFICE OF THE COMMISSIONER\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [225, 286, 593, 307], \"page_id\": 6}], \"content\": \"WASHINGTON, D.C. 20220\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1293, 161, 1571, 180], \"page_id\": 6}], \"content\": \"POSTAGE AND FEES PAID\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [1272, 187, 1573, 204], \"page_id\": 6}], \"content\": \"U.S. TREASURY DEPARTMENT\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [266, 331, 583, 360], \"page_id\": 6}], \"content\": \"OFFICIAL BUSINESS\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [282, 804, 1458, 1370], \"page_id\": 6}], \"content\": null, \"description\": null, \"id\": 7, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [0, 58, 1509, 296], \"page_id\": 7}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 0, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [555, 366, 996, 416], \"page_id\": 7}], \"content\": \"OCTOBER 1965\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [0, 902, 1608, 1902], \"page_id\": 7}], \"content\": null, \"description\": null, \"id\": 2, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [129, 1963, 1350, 2020], \"page_id\": 7}], \"content\": \"UNITED STATES TREASURY DEPARTMENT\", \"description\": null, \"id\": 3, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [488, 2047, 991, 2078], \"page_id\": 7}], \"content\": \"OFFICE OF THE SECRETARY\", \"description\": null, \"id\": 4, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [521, 950, 1180, 1020], \"page_id\": 8}], \"content\": \"The Treasury Bulletin is for sale by the Superintendent of Documents,\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [413, 1020, 1302, 1118], \"page_id\": 8}], \"content\": \"U. S. Government Printing Office, Washington D.C. 20402\\nSubscription per year $8.50 domestic, $11.00 foreign\\nSingle copy price varies\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [14, 22, 257, 65], \"page_id\": 9}], \"content\": \"October 1965\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1516, 22, 1533, 65], \"page_id\": 9}], \"content\": \"\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [581, 226, 948, 262], \"page_id\": 9}], \"content\": \"Table of Contents\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [1244, 363, 1328, 402], \"page_id\": 9}], \"content\": \"Page\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [223, 440, 1326, 1674], \"page_id\": 9}], \"content\": \"Treasury financing operations................ A-1\\nSummary of Federal fiscal operations............ 1\\nAdministrative budget receipts and expenditures. 2\\nTrust and other transactions.................... 9\\nConsolidated cash transactions.................. 14\\nAccount of the Treasurer of the United States... 17\\nDebt outstanding................................ 20\\nStatutory debt limitation....................... 25\\nPublic debt operations.......................... 26\\nUnited States savings bonds..................... 59\\nOwnership of Federal securities.................. 63\\nTreasury survey of ownership of Federal securities.................. 65\\nMarket quotations on Treasury securities....... 69\\nAverage yields of long-term bonds............... 72\\nMonetary statistics............................ 74\\nExchange Stabilization Fund..................... 77\\nInternational financial statistics.............. 79\\nCapital movements............................. 83\\nCumulative table of contents.................... 106\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [43, 53, 69, 82], \"page_id\": 10}], \"content\": \"II\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1289, 22, 1557, 79], \"page_id\": 10}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [668, 168, 916, 202], \"page_id\": 10}], \"content\": \"Reporting Bases\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [30, 250, 769, 645], \"page_id\": 10}], \"content\": \"Data on receipts, expenditures, and debt which appear in the \\\"Treasury Bulletin\\\" are based largely on two Treasury financial reports, the \\\"Daily Statement of the United States Treasury\\\" and the \\\"Monthly Statement of Receipts and Expenditures of the United States Government.\\\" Certain monetary statistics are based at least in part on the \\\"Circulation Statement of United States Money.\\\" Where these statements are given as sources for individual tables, they are cited by name only. Their respective reporting bases are described below. For other data in the Bulletin, information on sources or reporting bases is given in connection with the tables themselves.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [30, 650, 772, 1046], \"page_id\": 10}], \"content\": \"The monthly statement of receipts and expenditures was first published for February 1954, and replaced the daily statement as the primary source of information on budget results and other receipt and expenditure data classified by type of account. At the same time, the daily statement was changed to a statement of cash deposits and withdrawals affecting the account of the Treasurer of the United States. Both publications have provided comparative figures on their respective bases from the beginning of the fiscal year 1953. The announcement of February 17, 1954, with respect to these reporting changes may be found in the April 1954 issue of the Bulletin.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [32, 1053, 770, 1476], \"page_id\": 10}], \"content\": \"The monthly statement shows all receipts and expenditures of the Government, including those made from cash accounts held outside the United States Treasury. The information is compiled from reports by the Treasurer of the United States and by all other collecting and disbursing agencies, including those agencies which maintain checking accounts in commercial banks. These reports cover transactions recorded in the accounts of the agencies during the reporting period. The net of the transactions as compiled from these reports is reconciled in the monthly statement to changes in the balance in the Treasurer's account and in cash held outside the Treasurer's account and changes in the public debt outstanding.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [27, 1478, 767, 1941], \"page_id\": 10}], \"content\": \"Receipts of taxes and customs duties are reported on a collections basis. Other receipts are reported partially on a collections basis and partially on a deposits basis. Expenditures, except interest on the public debt, are reported on the basis of checks issued or cash payments made by disbursing officers. Transactions of an interfund or intragovernmental nature are included on the same basis even though the actual issuance of checks may not be involved. Interest on the public debt is included on an accrual basis beginning with figures for June 1955 and the fiscal year 1955. Prior to that, it was included on a due and payable basis. The same reporting basis as that in the monthly statement provides the fiscal year figures for the Treasury's \\\"Combined Statement of Receipts, Expend-\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [815, 247, 1569, 348], \"page_id\": 10}], \"content\": \"itures and Balances of the United States Government\\\" and for actual receipts and expenditures in the \\\"Budget of the United States Government.\\\"\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [818, 358, 1575, 1017], \"page_id\": 10}], \"content\": \"Beginning with the final statement for the fiscal year 1960, the monthly statement reports totals for net budget receipts and budget expenditures after deduction of certain interfund transactions which are included in the detail of both budget receipts and budget expenditures. The transactions deducted consist of interest payments and minor amounts of certain other payments made by Government agencies to the Treasury. This reporting change was made in accordance with the plan stated in the President's Budget Message of January 18, 1960. It does not affect the surplus or deficit. Figures for earlier periods shown in the Treasury Bulletin were revised to the new reporting basis in the September 1960 issue. The interfund transactions deducted under this procedure do not include payments to the Treasury by wholly owned Government corporations for retirement of their capital stock and for disposition of earnings. These capital transfers have been excluded currently from budget receipts and budget expenditures beginning July 1, 1948, and figures for prior fiscal years back through 1932 were revised accordingly at that time.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [818, 1022, 1578, 1579], \"page_id\": 10}], \"content\": \"The daily statement on the new basis was first issued for February 17, 1954. In the deposits and withdrawals as shown, no distinction is made as to the type of accounts (budget, trust, etc.). The deposits are on the basis of certificates of deposit cleared through the account of the Treasurer of the United States. Total withdrawals are on the basis of checks paid or cash disbursements made out of the Treasurer's account. Some of the withdrawal classifications shown are reported on the basis of mailed reports of checks issued and are adjusted by means of clearing accounts to the total of checks paid. Except for relatively minor amounts, noncash interfund and other intragovernmental transactions are excluded. The public debt figures in the daily statement also are on a \\\"clearance\\\" basis, with the exception of those issuance and retirement transactions reported on the basis of telegrams from Federal Reserve Banks. Noncash debt transactions are included, however.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [824, 1589, 1576, 1951], \"page_id\": 10}], \"content\": \"The daily statement before February 17, 1954, covered not only transactions cleared through the Treasurer's account but also certain Government agency transactions which were handled through commercial bank accounts, and included noncash interfund and other intragovernmental transactions. It provided information similar to that in the present daily statement with respect to the status of the Treasurer's account, and similar to that in the present end-of-month daily statement with respect to debt issuance, retirement, and amount outstanding. Receipts and expenditures, however, were classified by type of account, and the budget results shown\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [14, 12, 261, 59], \"page_id\": 11}], \"content\": \"October 1965\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1462, 19, 1509, 45], \"page_id\": 11}], \"content\": \"III\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [539, 145, 1002, 176], \"page_id\": 11}], \"content\": \"Reporting Bases - (Continued)\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [7, 209, 752, 304], \"page_id\": 11}], \"content\": \"in the daily statement were used as the basis for reflecting the results under the President's budget program as enacted by the Congress.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [12, 323, 752, 641], \"page_id\": 11}], \"content\": \"Receipts were on the basis of deposits as they cleared the Treasurer's account. Expenditures cleared through the Treasurer's account were reported on two successive bases. Through 1946 they were on the basis of checks paid by the Treasurer of the United States. Beginning with 1947, expenditures made through the facilities of the Treasury Department's Division of Disbursement were on the basis of checks issued, while certain others, principally those of the Department of Defense and its predecessor organizations, were on the basis of checks paid. Transactions han-\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [800, 216, 1518, 368], \"page_id\": 11}], \"content\": \"died through commercial bank accounts, consisting of market transactions in public debt and guaranteed securities, were as reported by the agencies. Interest on the public debt was included on a due and payable basis beginning with November 1949 and on a checks-paid basis prior to that time.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [798, 385, 1532, 641], \"page_id\": 11}], \"content\": \"The circulation statement reflects transactions through the Treasurer's account which affect monetary stocks of gold and silver and the amounts of coin and currency in the money supply of the country. It is issued later than the daily statement, however, and the figures are based on transactions consummated during the reporting period even though some may not have cleared the Treasurer's account during that period.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [29, 1874, 109, 1902], \"page_id\": 11}], \"content\": \"Note:\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [116, 1862, 1459, 1902], \"page_id\": 11}], \"content\": \"Where calculations have been made from unrounded figures, the details may not check to the totals shown.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [14, 28, 162, 74], \"page_id\": 13}], \"content\": \"October\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [182, 24, 264, 74], \"page_id\": 13}], \"content\": \"1965\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1470, 52, 1521, 86], \"page_id\": 13}], \"content\": \"A-1\", \"description\": null, \"id\": 2, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [511, 271, 1041, 311], \"page_id\": 13}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [18, 380, 305, 411], \"page_id\": 13}], \"content\": \"Tax Anticipation Bills\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [18, 411, 759, 603], \"page_id\": 13}], \"content\": \"The Treasury clarified its Autumn borrowing plans on September 22 with the announcement that the bulk of this financing would be provided by a $4 billion tax anticipation bill package that included $3 billion of March bills and $1 billion of June bills.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [18, 603, 759, 1050], \"page_id\": 13}], \"content\": \"Tenders were invited on September 22 for $3.0 billion, or thereabouts, of 162-day Treasury bills and $1.0 billion, or thereabouts, of 254-day Treasury bills. Both series are designated Tax Anticipation Series and are dated October 11, 1965. The 162-day bills mature March 22, 1966 and the 254-day bills mature June 22, 1966. They will be accepted at face value in payment of income taxes due on March 15, 1966 and June 15, 1966, respectively. To the extent they are not presented for this purpose the face amount will be payable without interest at maturity. Issued in bearer form only, the bills are in denominations of $1,000, $5,000, $10,000, $50,000, $100,000, $500,000, and $1,000,000 (maturity value).\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [18, 1054, 764, 1496], \"page_id\": 13}], \"content\": \"Tenders for the March bills, on the basis of preliminary reports, totaled $4,052 million, of which $3,009 million was accepted at the average bank discount rate of 3.783 percent. Of the $2,209 million tenders received for the June bills, also on the basis of preliminary reports, $1,003 million was accepted at the average bank discount rate of 3.941 percent. The March bill acceptances included noncompetitive tenders for $400,000 or less (without stated price) and the June acceptances included noncompetitive tenders for $200,000 or less (without stated price) from any one bidder at the average price of competitive bids. These amounted to $445 million for the March bills and $201 million for the June bills.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [18, 1501, 762, 1803], \"page_id\": 13}], \"content\": \"The usual requirements for the submission of tenders applied. Payment for accepted tenders in cash or other immediately available funds was required to be completed on October 11, 1965. Any qualified depositary was permitted to make payment by credit in its Treasury tax and loan account for Treasury bills allotted to it for itself and its customers up to the amount for which it was qualified in excess of existing deposits.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [25, 1841, 318, 1876], \"page_id\": 13}], \"content\": \"One-Year Bills Refunded\", \"description\": null, \"id\": 9, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [23, 1876, 768, 2107], \"page_id\": 13}], \"content\": \"Tenders were invited on September 16 for $1.0 billion, or thereabouts, of 365-day Treasury bills, for cash and in exchange for Treasury bills maturing September 30, 1965. Tenders totaling $2,970 million were received, of which $1,000 million was accepted, including $57 million of noncompetitive tenders, at the average bank discount rate of 4.236 percent.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [807, 420, 1525, 532], \"page_id\": 13}], \"content\": \"petitive tenders for $200,000 or less (without stated price) from any one bidder were accepted in full at the average price of accepted competitive bids.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [805, 527, 1532, 717], \"page_id\": 13}], \"content\": \"Payment for accepted tenders was required to be made or completed on September 30, 1965, in cash or other immediately available funds or in a like face amount of bills maturing on that date. Payment by credit in Treasury tax and loan accounts was not permitted.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [805, 712, 1532, 907], \"page_id\": 13}], \"content\": \"The new one-year bills are dated September 30, 1965, and will mature September 30, 1966, when the face amount will be payable without interest. Issued in bearer form only, the bills are in denominations of $1,000, $5,000, $10,000, $50,000, $100,000, $500,000, and $1,000,000 (maturity value).\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [812, 936, 1125, 971], \"page_id\": 13}], \"content\": \"13-Week and 26-Week Bills\", \"description\": null, \"id\": 14, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [804, 978, 1538, 1192], \"page_id\": 13}], \"content\": \"New issues of regular weekly Treasury bills in September totaled $11.0 billion, refunding an equivalent amount maturing. The September bills consisted of five 13-week issues of $1.2 billion each and five 26-week issues of $1.0 billion each. The bills carry 91-day and 182-day maturities. Average rates for the new issues are shown in the table following.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [805, 1247, 1530, 1755], \"page_id\": 13}], \"content\": \"<table><tr><th colspan=\\\"3\\\">13-week<br/>(Additional amount of bills of original maturity of 26 weeks)</th><th colspan=\\\"2\\\">26-week</th></tr><tr><th colspan=\\\"2\\\">Date of--</th><th>Approximate equivalent annual average rate 1/</th><th>Date of issue</th><th>Approximate equivalent annual average rate 1/</th></tr><tr><th>Additional issue</th><th>Original issue</th><th></th><th></th><th></th></tr><tr><td>1965<br>Sept. 2<br>9<br>16<br>23<br>30</td><td>1965<br>June 3<br>10<br>17<br>24<br>July 1</td><td>3.886<br>3.898<br>3.886<br>3.905<br>3.987</td><td>1965<br>Sept. 2<br>9<br>16<br>23<br>30</td><td>3.990<br>4.324<br>4.331<br>4.969<br>4.133</td></tr></table>\", \"description\": null, \"id\": 16, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [811, 1755, 1123, 1800], \"page_id\": 13}], \"content\": \"1/ Bank discount basis.\", \"description\": null, \"id\": 17, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [809, 1822, 1325, 1869], \"page_id\": 13}], \"content\": \"Foreign Series and Foreign Currency Series\", \"description\": null, \"id\": 18, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [809, 1869, 1538, 2092], \"page_id\": 13}], \"content\": \"In September the Treasury issued one certificate of indebtedness of the foreign series in the amount of $325 million and two bonds of the foreign currency series equivalent to $82 million. Retirements amounted to $135 million for the foreign series securities and the equivalent of $32 million for the foreign currency series.\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [50, 60, 101, 84], \"page_id\": 14}], \"content\": \"A-2\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1288, 43, 1559, 94], \"page_id\": 14}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [406, 204, 1199, 235], \"page_id\": 14}], \"content\": \"Treasury Financing Operations - (Continued)\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [46, 312, 774, 449], \"page_id\": 14}], \"content\": \"The new 3-month certificate, issued September 30, bears interest at the rate of 3.983 percent and matures December 30, 1965. As of September 30, the outstanding foreign series securities totaled $1,044 million.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [822, 310, 1553, 521], \"page_id\": 14}], \"content\": \"and matures October 7, 1966. The other, equivalent to $30 million, was issued September 27, bears interest at the rate of 4.23 percent and matures January 27, 1967. At the end of September foreign currency series outstanding totaled $1,259 million and were denominated in Austrian schillings, Belgian francs, German marks, Italian lire and Swiss francs.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [48, 458, 776, 559], \"page_id\": 14}], \"content\": \"The new bonds of the foreign currency series are denominated in Swiss francs. One, equivalent to $52 million, was issued September 7, bears interest at the rate of 4.10 percent\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [43, 2061, 1541, 2112], \"page_id\": 14}], \"content\": \"Note: Details of Treasury market financing operations are shown elsewhere in this issue of the Bulletin in the tables on public debt operations.\", \"description\": null, \"id\": 6, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [20, 26, 279, 81], \"page_id\": 15}], \"content\": \"October 1965\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1509, 52, 1546, 95], \"page_id\": 15}], \"content\": \"1\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [552, 142, 1050, 178], \"page_id\": 15}], \"content\": \"SUMMARY OF FEDERAL FISCAL OPERATIONS\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [671, 180, 912, 214], \"page_id\": 15}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [25, 216, 1536, 1679], \"page_id\": 15}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">Period</th><th colspan=\\\"3\\\">Administrative budget receipts and expenditures</th><th rowspan=\\\"2\\\">Net of trust and other transactions 1/</th><th rowspan=\\\"2\\\">Clearing account, etc. 2/</th><th rowspan=\\\"2\\\">Net increase in public debt, or decrease (-)</th><th rowspan=\\\"2\\\">Net increase in Treasurer's account, or decrease (-)</th><th colspan=\\\"4\\\">Levels, end of period</th></tr><tr><th>Net receipts</th><th>Expenditures</th><th>Surplus, or deficit (-)</th><th>Treasurer's account balance</th><th colspan=\\\"3\\\">Debt outstanding</th></tr><tr><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th>Public debt</th><th>Guaranteed securities</th><th>Total Federal securities</th><th>Subject to limitation 3/</th></tr><tr><td>Fiscal years:</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>1950</td><td>36,422</td><td>39,544</td><td>-3,122</td><td>