1,\n    1958: 0.3571,\n    1959: 0.3571,\n    1960: 0.3571,\n    1961: 0.3571,\n    1962: 0.3571,\n    1963: 0.3571,\n    1964: 0.3571,\n}\n\n# Convert to GBP (in millions)\ndata_GBP = []\nfor year in range(1948, 1965):\n    rate = exchange_rates[year]\n    receipts_gbp = treasury_data[year]['receipts'] * rate\n    exp_gbp = treasury_data[year]['expenditures'] * rate\n    data_GBP.append({\n        'year': year,\n        'receipts_gbp': receipts_gbp,\n        'expenditures_gbp': exp_gbp,\n        'usd_rate': rate\n    })\n    print(f\"{year}: R=${treasury_data[year]['receipts']}M, E=${treasury_data[year]['expenditures']}M => R=£{receipts_gbp:.2f}M, E=£{exp_gbp:.2f}M (rate={rate})\")\n\n# Now calculate Pearson correlation coefficient\n# r = cov(X,Y) / (std(X) * std(Y))\n\n# Extract values\nreceipts = [d['receipts_gbp'] for d in data_GBP]\nexpenditures = [d['expenditures_gbp'] for d in data_GBP]\n\nn = len(receipts)\n\n# Calculate means\nmean_r = sum(receipts) / n\nmean_e = sum(expenditures) / n\n\n# Calculate covariance\ncov = sum((receipts[i] - mean_r) * (expenditures[i] - mean_e) for i in range(n)) / (n - 1)\n\n# Calculate standard deviations\nstd_r = math.sqrt(sum((r - mean_r) ** 2 for r in receipts) / (n - 1))\nstd_e = math.sqrt(sum((e - mean_e) ** 2 for e in expenditures) / (n - 1))\n\n# Pearson correlation\npearson_r = cov / (std_r * std_e)\n\nprint(f\"\\n=== Results ===\")\nprint(f\"Mean receipts (GBP millions): {mean_r:.2f}\")\nprint(f\"Mean expenditures (GBP millions): {mean_e:.2f}\")\nprint(f\"Standard deviation receipts: {std_r:.2f}\")\nprint(f\"Standard deviation expenditures: {std_e:.2f}\")\nprint(f\"Covariance: {cov:.2f}\")\nprint(f\"Pearson correlation coefficient: {pearson_r:.4f}\")\nprint(f\"Pearson correlation coefficient (rounded to 2 decimal places): {pearson_r:.2f}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
