 a clear calculation\nimport math\n\n# Data from treasury bulletins\n# Using most recent data per year requirement\n\n# Fiscal year USD data (millions)\ntreasury_usd = {\n    1948: (41375, 32955),  # receipts, expenditures\n    1949: (37663, 39474),\n    1950: (36422, 39544),\n    1951: (47480, 43970),\n    1952: (61287, 65303),\n    1953: (64671, 74120),\n    1954: (64420, 67537),\n    1955: (60209, 64389),\n    1956: (67850, 66224),\n    1957: (70562, 68966),\n    1958: (68550, 71369),\n    1959: (67915, 80342),\n    1960: (77763, 76539),  # From 1965 bulletin (more recent)\n    1961: (77659, 81515),\n    1962: (81409, 87787),\n    1963: (86376, 92642),\n    1964: (89459, 97684),\n}\n\n# Exchange rates (GBP per 1 USD)\n# During Bretton Woods:\n# 1948-1949: $4.03 = £1, so $1 = £0.2481\n# 1950-1964: $2.80 = £1, so $1 = £0.3571\ngbp_per_usd = {\n    1948: 0.2481,\n    1949: 0.2481,\n    1950: 0.3571,\n    1951: 0.3571,\n    1952: 0.3571,\n    1953: 0.3571,\n    1954: 0.3571,\n    1955: 0.3571,\n    1956: 0.3571,\n    1957: 0.3571,\n    1958: 0.3571,\n    1959: 0.3571,\n    1960: 0.3571,\n    1961: 0.3571,\n    1962: 0.3571,\n    1963: 0.3571,\n    1964: 0.3571,\n}\n\n# Convert to GBP\nreceipts_gbp = []\nexpenditures_gbp = []\n\nfor year in range(1948, 1965):\n    r, e = treasury_usd[year]\n    rate = gbp_per_usd[year]\n    receipts_gbp.append(r * rate)\n    expenditures_gbp.append(e * rate)\n\n# Calculate Pearson correlation coefficient\nn = len(receipts_gbp)\nmean_r = sum(receipts_gbp) / n\nmean_e = sum(expenditures_gbp) / n\n\ncov = sum((receipts_gbp[i] - mean_r) * (expenditures_gbp[i] - mean_e) for i in range(n)) / (n - 1)\nstd_r = math.sqrt(sum((r - mean_r) ** 2 for r in receipts_gbp) / (n - 1))\nstd_e = math.sqrt(sum((e - mean_e) ** 2 for e in expenditures_gbp) / (n - 1))\n\nr = cov / (std_r * std_e)\n\nprint(f\"Years analyzed: 1948-1964 ({n} years)\")\nprint(f\"Exchange rates: 1948-1949: {gbp_per_usd[1948]} GBP/USD, 1950-1964: {gbp_per_usd[1950]} GBP/USD\")\nprint(f\"\\nMean Receipts (GBP): £{mean_r:,.2f}M\")\nprint(f\"Mean Expenditures (GBP): £{mean_e:,.2f}M\")\nprint(f\"\\nCovariance: {cov:,.2f}\")\nprint(f\"Std Dev Receipts: {std_r:,.2f}\")\nprint(f\"Std Dev Expenditures: {std_e:,.2f}\")\nprint(f\"\\nPearson Correlation Coefficient: {r:.4f}\")\nprint(f\"Rounded to 2 decimal places: {r:.2f}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
